EXAMEN = [
  Q('« Little ___ that he was watching. »', ['I knew', 'did I know', 'I did know'], 1, 'Inversion.'),
  Q('« It was Kenza ___ won the prize. »', ['which', 'who', 'what'], 1, 'It was… who…'),
  Q('« ___ I known, I would have come. »', ['Had', 'Have', 'If had'], 0, 'Had I known.'),
  Q('« He ___ have forgotten — he never forgets! »', ['must', 'can\'t', 'might'], 1, 'can\'t have.'),
  Q('« We ran ___ of money. »', ['off', 'out', 'away'], 1, 'run out of.'),
  Q('Most academic:', ['It\'s clear that people hate it.', 'It appears that many people are reluctant.', 'Everybody hates it.'], 1, 'Hedging.'),
  Q('A good speech opening:', ['Um, so, yeah…', 'Have you ever wondered why…?', 'I don\'t know what to say.'], 1, 'Rhetorical question.'),
  Q('« I\'ll think about it » often means…', ['Yes, definitely.', 'Probably not.', 'Tomorrow.'], 1, 'Indirect no.'),
  Q('« Certes » =', ['Granted', 'Therefore', 'Moreover'], 0, 'Granted.'),
  Q('« Should you require help » =', ['If you require help', 'You must require help', 'You should help'], 0, 'If you…'),
  T('Ce qui compte, c\'est l\'effort.', 'What matters is the effort.', 'What counts is the effort.', 'What matters is effort.'),
  O('Never have I learned so much in so little time', 'Jamais je n\'ai autant appris en si peu de temps'),
]

def main():
    dossier = os.path.join(ICI, 'n5')
    os.makedirs(dossier, exist_ok=True)
    for i, l in enumerate(LECONS, start=1):
        doc = {'id': 'en-n5-l%02d' % i, 'langue': 'en', 'niveau': 5, 'lecon': i, 'cecrl': 'C1', **l}
        with open(os.path.join(dossier, 'l%02d.json' % i), 'w', encoding='utf-8') as f:
            json.dump(doc, f, ensure_ascii=False, indent=1)
    with open(os.path.join(dossier, 'examen.json'), 'w', encoding='utf-8') as f:
        json.dump({'id': 'en-n5-examen', 'langue': 'en', 'niveau': 5, 'reussite': 9, 'etapes': EXAMEN}, f, ensure_ascii=False, indent=1)
    print(len(LECONS), 'leçons écrites')

if __name__ == '__main__':
    main()
